enum AuthProvider { Lti = 1, Oidc = 2 }

sealed class HeaderMap
{
    private readonly Dictionary<string, string> _headers = new(StringComparer.OrdinalIgnoreCase);
    public string this[string name]
    {
        get => _headers[name];
        set => _headers[name] = value;
    }
}

static (AuthProvider provider, string issuer) Parse(string raw)
{
    return raw.StartsWith("lti:", StringComparison.Ordinal)
        ? (AuthProvider.Lti, raw[4..])
        : (AuthProvider.Oidc, raw);
}

[Flags]
enum FileAccess { None = 0, Read = 1, Write = 2, Execute = 4 }

static string Describe(FileAccess access) => access switch
{
    FileAccess.None => "no access",
    FileAccess.Read => "read only",
    FileAccess.Read | FileAccess.Write => "read-write",
    _ => $"unknown ({(int)access})"
};

static (string tenant, int attemptNo) ParseAttempt(string raw)
{
    var parts = raw.Split(':');
    return (parts[0], int.Parse(parts[1]));
}

var (tenant, attemptNo) = ParseAttempt("acme:42");
Console.WriteLine($"{tenant} attempt {attemptNo}");
